1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import java.util.function.Consumer;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 */
19	@Profile("harness")
20	@RestController
21	@RequestMapping("/__test__")
22	public class TestSupportController {
23	
24	    private final Audit audit;
25	    private final JdbcTemplate jdbc;
26	
27	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
28	        this.audit = audit;
29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * Domain tables in FK-dependency order (child before parent). Referential integrity is dropped
34	     * around the truncates so the order is not load-bearing, but keeping it sensible documents the
35	     * shape. A new table joins the reset by being added to this list — no new statement to write.
36	     */
37	    private static final List<String> DOMAIN_TABLES =
38	            List.of("note", "project_tag", "tag", "payment", "line_item", "invoice", "task",
39	                    "contact", "project", "client", "app_setting");
40	
41	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
42	    @PostMapping("/reset")
43	    public void reset() {
44	        audit.clear();
45	        // Drop referential integrity around the truncates: RESTART IDENTITY on each, then restore
46	        // it. That makes the order above cosmetic and clears every FK-referenced table cleanly.
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
48	        for (String table : DOMAIN_TABLES) {
49	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
50	        }
51	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
52	    }
53	
54	    /**
55	     * Insert the fixture a spec needs; the payload shape evolves with the schema. Each table is one
56	     * {@link #seedRows} call: name the fixture key, then map a row to an INSERT. A new table is one
57	     * more call here — the null-check and per-row loop are shared, not repeated.
58	     */
59	    @PostMapping("/seed")
60	    public void seed(@RequestBody Map<String, Object> fixture) {
61	        seedRows(fixture, "clients", c -> jdbc.update(
62	                "INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
63	                asLong(c, "id"), c.get("name"), c.get("email")));
64	
65	        seedRows(fixture, "projects", p -> jdbc.update(
66	                "INSERT INTO project (id, name, client_id, status, archived, budget, code) "
67	                        + "VALUES (?, ?, ?, ?, ?, ?, ?)",
68	                asLong(p, "id"), p.get("name"), asLong(p, "clientId"),
69	                p.get("status") == null ? "ACTIVE" : p.get("status"),
70	                Boolean.TRUE.equals(p.get("archived")),
71	                p.get("budget") == null ? 0 : p.get("budget"),
72	                p.get("code")));
73	
74	        seedRows(fixture, "tasks", t -> jdbc.update(
75	                "INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
76	                asLong(t, "id"), asLong(t, "projectId"), t.get("title"),
77	                Boolean.TRUE.equals(t.get("done"))));
78	
79	        seedRows(fixture, "tags", t -> jdbc.update(
80	                "INSERT INTO tag (id, name) VALUES (?, ?)",
81	                asLong(t, "id"), t.get("name")));
82	
83	        // A project_tag row is a (project, tag) pairing with no id of its own in the fixture — let the
84	        // IDENTITY column assign one (GENERATED BY DEFAULT allows the omission).
85	        seedRows(fixture, "projectTags", pt -> jdbc.update(
86	                "INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
87	                asLong(pt, "projectId"), asLong(pt, "tagId")));
88	
89	        seedRows(fixture, "notes", n -> jdbc.update(
90	                "INSERT INTO note (id, target_type, target_id, note_text, created_at) "
91	                        + "VALUES (?, ?, ?, ?, ?)",
92	                asLong(n, "id"), n.get("targetType"), asLong(n, "targetId"),
93	                n.get("text"), n.get("at")));
94	        // The seed inserts explicit ids into note's IDENTITY column (GENERATED BY DEFAULT), which does
95	        // not advance the identity sequence — reset RESTARTed it at 1. Without this the first app-side
96	        // save() would regenerate id=1 and collide with a seeded row. Advance it past the max seeded
97	        // id so a note added through the API (POST /api/notes) gets a fresh id.
98	        syncIdentity("note");
99	
100	        seedRows(fixture, "contacts", c -> jdbc.update(
101	                "INSERT INTO contact (id, client_id, name, email, role, is_primary) "
102	                        + "VALUES (?, ?, ?, ?, ?, ?)",
103	                asLong(c, "id"), asLong(c, "clientId"),
104	                c.get("name"), c.get("email"), c.get("role"),
105	                Boolean.TRUE.equals(c.get("primary"))));
106	        syncIdentity("contact");
107	
108	        // An invoice is now itemised: its amount is the sum of qty * unit price across its lines
109	        // (nested under the invoice in the fixture). The stored amount is the derived total — the
110	        // fixture may still supply an explicit "amount" for an invoice with no lines, otherwise it
111	        // is computed here so the invoice list reads the same total the lines add up to.
112	        seedRows(fixture, "invoices", i -> {
113	            List<Map<String, Object>> lines = asRows(i.get("lineItems"));
114	            double computed = 0;
115	            for (Map<String, Object> li : lines) {
116	                computed += ((Number) li.get("qty")).doubleValue()
117	                        * ((Number) li.get("unitPrice")).doubleValue();
118	            }
119	            Object explicit = i.get("amount");
120	            double amount = explicit == null ? computed : ((Number) explicit).doubleValue();
121	            // An optional percentage discount off the invoice's subtotal (0 when the fixture omits it).
122	            // The discount amount and the final total are derived from it (see InvoiceSummaryGet).
123	            Object discountPct = i.get("discountPct");
124	            // An optional sales-tax percentage added on top after the discount (0 when the fixture
125	            // omits it). The tax amount and the final taxed total are derived from it (see
126	            // InvoiceSummaryGet).
127	            Object taxPct = i.get("taxPct");
128	            jdbc.update(
129	                    "INSERT INTO invoice "
130	                            + "(id, project_id, amount, status, issued_date, due_date, discount_pct, tax_pct) "
131	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
132	                    asLong(i, "id"), asLong(i, "projectId"), amount,
133	                    i.get("status") == null ? "UNPAID" : i.get("status"),
134	                    i.get("issuedDate"), i.get("dueDate"),
135	                    discountPct == null ? 0 : discountPct,
136	                    taxPct == null ? 0 : taxPct);
137	            for (Map<String, Object> li : lines) {
138	                jdbc.update(
139	                        "INSERT INTO line_item (id, invoice_id, description, qty, unit, unit_price) "
140	                                + "VALUES (?, ?, ?, ?, ?, ?)",
141	                        asLong(li, "id"), asLong(i, "id"), li.get("description"),
142	                        ((Number) li.get("qty")).intValue(),
143	                        li.get("unit") == null ? "unit" : li.get("unit"),
144	                        ((Number) li.get("unitPrice")).doubleValue());
145	            }
146	        });
147	
148	        // A payment a client has made against an invoice: how much and on what day. Seeded at the
149	        // fixture's explicit id (GENERATED BY DEFAULT allows it); syncIdentity below advances the
150	        // sequence so an app-side save() (POST /api/payments) gets a fresh id.
151	        seedRows(fixture, "payments", p -> jdbc.update(
152	                "INSERT INTO payment (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
153	                asLong(p, "id"), asLong(p, "invoiceId"),
154	                ((Number) p.get("amount")).doubleValue(), p.get("date")));
155	        syncIdentity("payment");
156	
157	        // A scalar top-level setting rather than a list of rows: the dashboard's "as of" reference
158	        // date, the fixed day overdue is measured against. Stored in the app_setting key/value table
159	        // so the dashboard reads a deterministic reference date.
160	        Object asOf = fixture.get("asOf");
161	        if (asOf != null) {
162	            jdbc.update("INSERT INTO app_setting (setting_key, setting_value) VALUES ('asOf', ?)",
163	                    asOf.toString());
164	        }
165	    }
166	
167	    /** A nested optional list of rows (e.g. an invoice's line items), or empty when the key is absent. */
168	    @SuppressWarnings("unchecked")
169	    private static List<Map<String, Object>> asRows(Object value) {
170	        return value == null ? List.of() : (List<Map<String, Object>>) value;
171	    }
172	
173	    /**
174	     * Run {@code insert} for each row under {@code key}, or do nothing if the fixture omits that key.
175	     * This is the shared "optional list of rows" shape every table seed follows.
176	     */
177	    @SuppressWarnings("unchecked")
178	    private void seedRows(Map<String, Object> fixture, String key,
179	            Consumer<Map<String, Object>> insert) {
180	        List<Map<String, Object>> rows = (List<Map<String, Object>>) fixture.get(key);
181	        if (rows == null) {
182	            return;
183	        }
184	        for (Map<String, Object> row : rows) {
185	            insert.accept(row);
186	        }
187	    }
188	
189	    /**
190	     * Advance {@code table}'s IDENTITY sequence past its current max id, so app-side {@code save()}
191	     * calls that generate ids do not collide with rows the seed inserted at explicit ids.
192	     */
193	    private void syncIdentity(String table) {
194	        Long max = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM " + table, Long.class);
195	        if (max != null && max > 0) {
196	            jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + (max + 1));
197	        }
198	    }
199	
200	    /** Read a JSON number field as a {@code long} (JSON integers arrive as {@link Number}). */
201	    private static long asLong(Map<String, Object> row, String key) {
202	        return ((Number) row.get(key)).longValue();
203	    }
204	}
