---invoiceStatus.ts---
// Work out an invoice's status from the payments recorded against it — no longer flipped to paid by
// hand. The server sends each invoice's amount and its amountDue (amount minus every payment); the
// status follows from what is still owed:
//   PAID    — nothing left to pay (payments cover the amount)
//   PARTIAL — some has been paid but not all
//   else    — nothing paid yet, so its lifecycle status stands (DRAFT until sent, then SENT)
// Kept in one shared place so the project invoices row and the invoice-detail panel read the same
// derived value (the test contract: SENT, PARTIAL, PAID).
export function invoiceStatus(invoice: {
  amount: number;
  amountDue: number;
  status: string;
}): string {
  const amount = Number(invoice.amount);
  const due = Number(invoice.amountDue);
  if (amount > 0 && due <= 0) {
    return 'PAID';
  }
  if (due < amount) {
    return 'PARTIAL';
  }
  return invoice.status;
}
---dueAmount.slot.tsx---
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { InvoiceRowCells } from '../../slots/defs/invoiceRowCells';
import { money } from '../../ui/money';
import type { Invoice } from './InvoicesPanel';

// The "amount still due" cell of an invoice row — its own file, filling the invoice-row-cells slot.
// The panel is not edited to know how the due amount is worked out: this cell queries for itself
// (['invoices'], the SAME key the panel owns) and reads the invoice's server-derived amountDue (its
// amount minus every payment recorded against it), so it stays in step whenever a payment changes
// and the list is invalidated. Carries data-testid="invoice-due-amount" (the test contract).
export const contribution = InvoiceRowCells.fill({
  order: 10,
  Component: ({ invoiceId }: { invoiceId: number }) => {
    const invoices = useQuery({
      queryKey: ['invoices'],
      queryFn: () => getJson<Invoice[]>('/api/invoices'),
    });
    const invoice = (invoices.data ?? []).find((i) => i.id === invoiceId);
    const due = invoice ? Number(invoice.amountDue) : 0;
    return <td data-testid="invoice-due-amount">{money(due)}</td>;
  },
});
---status.slot.tsx---
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { InvoiceDetail } from '../../slots/defs/invoiceDetail';
import { invoiceStatus } from '../../ui/invoiceStatus';
import type { Invoice } from './InvoicesPanel';

// The invoice's status on its detail page — its own file, filling the invoice-detail slot above the
// line items. It is worked out from the payments, not stored: this panel queries for itself
// (['invoices'], the SAME key the amount-due cell owns) and derives the status from the invoice's
// amount and amountDue. Recording a payment invalidates ['invoices'], so the status refreshes from
// SENT to PARTIAL to PAID as the invoice is paid off. Carries data-testid="invoice-status".
export const contribution = InvoiceDetail.fill({
  order: 5,
  Component: ({ invoiceId }: { invoiceId: number }) => {
    const invoices = useQuery({
      queryKey: ['invoices'],
      queryFn: () => getJson<Invoice[]>('/api/invoices'),
    });
    const invoice = (invoices.data ?? []).find((i) => i.id === invoiceId);
    return (
      <section data-testid="invoice-status-panel">
        Status: <span data-testid="invoice-status">{invoice ? invoiceStatus(invoice) : ''}</span>
      </section>
    );
  },
});
---invoiceRowCells def---
import { defineSlot } from '../Slot';

/**
 * The per-row cell region of the project invoices table. Each invoice row renders this with its own
 * id; features fill it with extra `<td>` cells (e.g. the amount still due after payments) without the
 * list ever listing what cells it grows. Mirrors {@link ProjectRowActions}: the context is the
 * invoice's id, so a contribution can scope its own data to that invoice.
 */
export const InvoiceRowCells = defineSlot<{ invoiceId: number }>('invoice.row.cells');
---money.ts---
// How money renders across the app: a dollar sign, thousands separators, and two decimals, like
// $1,234.50. Kept in one shared place so every amount — invoice rows, the project total, the
// client statement, the dashboard outstanding total — formats identically (the test contract).
export function money(amount: number): string {
  return `$${amount.toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

